package com.stocksense.common; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import java.time.Instant; import java.util.Map; @RestControllerAdvice public class ApiExceptionHandler { @ExceptionHandler({IllegalArgumentException.class,IllegalStateException.class}) ResponseEntity<?> bad(RuntimeException e){return ResponseEntity.badRequest().body(Map.of("timestamp",Instant.now().toString(),"status",400,"message",e.getMessage()));} @ExceptionHandler(Exception.class) ResponseEntity<?> all(Exception e){return ResponseEntity.status(500).body(Map.of("timestamp",Instant.now().toString(),"status",500,"message",e.getMessage()==null?"Unexpected error":e.getMessage()));} }
